 68	+pub(crate) const STILL_THINKING_SECS: u64 = 10;
 69	+
 70	+/// 配色档②（亮橙）触发秒数（见 PRD §2.7）
 71	+pub(crate) const HEAT_LV2_SECS: u64 = 5;
 72	+/// 配色档③（浅黄）触发秒数（见 PRD §2.7）
 73	+pub(crate) const HEAT_LV3_SECS: u64 = 15;
 74	+/// 配色档④（终黄）触发秒数（见 PRD §2.7）
 75	+pub(crate) const HEAT_LV4_SECS: u64 = 30;
 76	+
 77	+/// spinner 第三字段（状态词）文案。空白表示不显示。
 78	+///
 79	+/// - `thinking`：正在思考且当前段未超阈
 80	+/// - `still thinking`：正在思考且当前段超 [`STILL_THINKING_SECS`]（优先级最高）
 81	+/// - `thinking more`：本轮已产出过、再次思考（`round >= 2`）
 82	+/// - 空：不在思考段（工具执行 / 出文本）
 83	+pub(crate) fn thinking_status_word(
 84	+    is_thinking: bool,
 85	+    thinking_elapsed_ms: u64,
 86	+    round: u32,
 87	+) -> &'static str {
 88	+    if !is_thinking {
 89	+        return "";
 90	+    }
 91	+    if thinking_elapsed_ms / 1000 >= STILL_THINKING_SECS {
 92	+        "still thinking"
 93	+    } else if round >= 2 {
 94	+        "thinking more"
 95	+    } else {
 96	+        "thinking"
 97	+    }
 98	+}
