100	+/// 按「当前思考段耗时」返回 verb / 状态词的热度色（四档，见 PRD §2.7）。
101	+/// 非思考段（工具执行）由调用方沿用上一档，此函数只按传入耗时计算。
102	+pub(crate) fn thinking_heat_color(thinking_elapsed_ms: u64) -> ratatui::style::Color {
103	+    let secs = thinking_elapsed_ms / 1000;
104	+    if secs >= HEAT_LV4_SECS {
105	+        theme::WARNING
106	+    } else if secs >= HEAT_LV3_SECS {
107	+        theme::SPINNER_HEAT_LV3
108	+    } else if secs >= HEAT_LV2_SECS {
109	+        theme::SPINNER_HEAT_LV2
110	+    } else {
111	+        theme::ACCENT
112	+    }
113	+}
