135	+fn make_ai_with_tools(tools: &[(&str, &str)]) -> Vec<BaseMessage> {
136	+    let mut tool_calls = Vec::new();
137	+    for (i, &(name, arg)) in tools.iter().enumerate() {
138	+        tool_calls.push(ToolCallRequest {
139	+            id: format!("tc{i}"),
140	+            name: name.to_string(),
141	+            arguments: if name == "Bash" {
142	+                json!({ "command": arg })
143	+            } else if name == "Glob" || name == "Grep" {
144	+                json!({ "pattern": arg })
145	+            } else {
146	+                json!({ "file_path": arg })
147	+            },
148	+        });
149	+    }
150	+    let mut msgs = vec![
151	+        BaseMessage::human("查一下"),
152	+        BaseMessage::Ai {
153	+            id: peri_agent::messages::MessageId::new(),
154	+            content: MessageContent::blocks(vec![ContentBlock::Reasoning {
155	+                text: "先看看文件".to_string(),
156	+                signature: None,
157	+                duration_ms: Some(4000),
158	+            }]),
159	+            tool_calls: tool_calls.clone(),
160	+        },
161	+    ];
162	+    for tc in &tool_calls {
163	+        msgs.push(BaseMessage::Tool {
164	+            id: peri_agent::messages::MessageId::new(),
165	+            tool_call_id: tc.id.clone(),
166	+            content: MessageContent::text("结果"),
167	+            is_error: false,
168	+        });
169	+    }
170	+    msgs
171	+}
