294	+/// 只读工具动作计数文案（PRD §2.3）：
295	+/// `read N file(s)` / `listed N director(y|ies)` / `searched for N pattern(s)`
296	+pub(crate) fn readonly_action_summary(reads: usize, globs: usize, greps: usize) -> Option<String> {
297	+    let mut parts = Vec::new();
298	+    if reads > 0 {
299	+        parts.push(format!(
300	+            "read {reads} file{}",
301	+            if reads > 1 { "s" } else { "" }
302	+        ));
303	+    }
304	+    if globs > 0 {
305	+        parts.push(format!(
306	+            "listed {globs} director{}",
307	+            if globs > 1 { "ies" } else { "y" }
308	+        ));
309	+    }
310	+    if greps > 0 {
311	+        parts.push(format!(
312	+            "searched for {greps} pattern{}",
313	+            if greps > 1 { "s" } else { "" }
314	+        ));
315	+    }
316	+    if parts.is_empty() {
317	+        None
318	+    } else {
319	+        Some(parts.join(", "))
320	+    }
321	+}
