323	+/// 后处理：为「末尾 block 是 Reasoning」的 AssistantBubble 注入其**紧随的只读工具计数**。
324	+///
325	+/// 结构形如：
326	+/// ```text
327	+/// AssistantBubble[.. Reasoning]     ← 注入目标
328	+/// ToolCallGroup(Read / Glob / Grep) ← 紧邻的只读工具（aggregate 折叠后）
329	+/// ```
330	+/// 结果写入 Reasoning block 的 `action_summary`，渲染为 `Thought for Ns, read 1 file`。
331	+fn inject_action_summary(vms: &mut [MessageViewModel]) {
332	+    for i in 0..vms.len() {
333	+        // 目标：含 Reasoning block 的 AssistantBubble（不要求 Reasoning 在末尾——
334	+        // tool_calls 会被追加到 blocks 末尾，故末尾通常是 ToolUse）
335	+        let is_target = matches!(
336	+            &vms[i],
337	+            MessageViewModel::AssistantBubble { blocks, .. }
338	+                if blocks
339	+                    .iter()
340	+                    .any(|b| matches!(b, ContentBlockView::Reasoning { .. }))
341	+        );
342	+        if !is_target {
343	+            continue;
344	+        }
345	+
346	+        // 扫描其后**连续**的只读工具 VM，累计计数
347	+        let (mut reads, mut globs, mut greps) = (0usize, 0usize, 0usize);
348	+        for vm in vms.iter().skip(i + 1) {
349	+            match vm {
350	+                MessageViewModel::ToolCallGroup { tools, .. } => {
351	+                    for t in tools {
352	+                        match t.tool_name.as_str() {
353	+                            "Read" => reads += 1,
354	+                            "Glob" => globs += 1,
355	+                            "Grep" => greps += 1,
356	+                            _ => {}
357	+                        }
358	+                    }
359	+                }
360	+                MessageViewModel::ToolBlock { tool_name, .. } => match tool_name.as_str() {
361	+                    "Read" => reads += 1,
362	+                    "Glob" => globs += 1,
363	+                    "Grep" => greps += 1,
364	+                    _ => break, // 非只读工具（Bash/Write/…）→ 停止
365	+                },
366	+                _ => break, // 非工具 VM → 停止
367	+            }
368	+        }
369	+
370	+        let Some(summary) = readonly_action_summary(reads, globs, greps) else {
371	+            continue;
372	+        };
373	+        // 注入到该 bubble 中**最后一个** Reasoning block
374	+        if let MessageViewModel::AssistantBubble { blocks, .. } = &mut vms[i] {
375	+            if let Some(ContentBlockView::Reasoning { action_summary, .. }) = blocks
376	+                .iter_mut()
377	+                .rev()
378	+                .find(|b| matches!(b, ContentBlockView::Reasoning { .. }))
379	+            {
380	+                *action_summary = Some(summary);
381	+            }
382	+        }
383	+    }
384	+}
